WITH valid_orders AS (SELECT * FROM orders WHERE amount < 1550), Agg AS (SELECT CASE WHEN shipping_fee >= 44 THEN 'high' WHEN shipping_fee >= 9 THEN 'mid' ELSE 'low' END AS shipping_fee_bucket, COUNT(*) AS order_count FROM valid_orders GROUP BY CASE WHEN shipping_fee >= 44 THEN 'high' WHEN shipping_fee >= 9 THEN 'mid' ELSE 'low' END) SELECT shipping_fee_bucket, order_count FROM Agg WHERE order_count >= 9 ORDER BY 1 DESC, order_count DESC LIMIT 3;
